import{c as e,Q as r,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"跨模型 Harness 激盪：ChatGPT 5.5 codex-rewrite vs 現有 Zeuik harness — 論文驗證、多維 pilot 評審與融合草案","description":"","frontmatter":{"title":"跨模型 Harness 激盪：ChatGPT 5.5 codex-rewrite vs 現有 Zeuik harness — 論文驗證、多維 pilot 評審與融合草案","date":"2026-06-23T00:00:00.000Z","status":"draft-for-decision","branch":"feature/chatgpt55-harness-crossbreed","papers_validated":"60+","tags":["harness-engineering","the-loop","cross-model","codex-rewrite","autoload-evolution","multi-pilot-review"],"type":"research-report","workflow":"crossmodel-harness-crossbreed (17 agents, 971K tokens, 585s)"},"headers":[],"relativePath":"research/reports/2026-06-23-crossmodel-harness-crossbreed.md","filePath":"research/reports/2026-06-23-crossmodel-harness-crossbreed.md","lastUpdated":1785909234000}'),s={name:"research/reports/2026-06-23-crossmodel-harness-crossbreed.md"};function n(i,t,l,d,c,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="跨模型-harness-激盪研究報告" tabindex="-1">跨模型 Harness 激盪研究報告 <a class="header-anchor" href="#跨模型-harness-激盪研究報告" aria-label="Permalink to &quot;跨模型 Harness 激盪研究報告&quot;">​</a></h1><blockquote><p><strong>一句話結論</strong>：現有 Zeuik harness 在繁中處理與接地（grounding/substrate wiring）<strong>決定性勝</strong>；ChatGPT 5.5 codex-rewrite 在 typed backbone（四 runtime 能力框架、ETCLOVG 失敗詞彙、具名 Task-Contract、5-tier risk）與 byte 成本勝。融合方向 = <strong>Zeuik 已驗證 substrate「掛」上 ChatGPT 5.5 的 typed backbone</strong>——但經對抗稽核，原 5 條融合規則須降為 <strong>1 條 HIGH_VALUE（R3 Handoff Contract）優先落地</strong>，其餘壓縮/refs 化/DROP，且<strong>嚴守 ≤1 規則/cycle + byte cap 不上調</strong>。</p></blockquote><h2 id="_0-任務與方法" tabindex="-1">0. 任務與方法 <a class="header-anchor" href="#_0-任務與方法" aria-label="Permalink to &quot;0. 任務與方法&quot;">​</a></h2><p><strong>Goal</strong>：① 兩家 harness 逐條對照報告；② 判定哪版在繁中 + workspace 彈性（29 SKILLS / ~18 AGENTS / HOOKS / REFS）下更優；③ 激盪出更有價值的融合 harness 規則（先報告、套用待裁決）；④ 用 4 pilot 多維 + multi-mode-agent 審閱論文加強落地對照。</p><p><strong>方法（dynamic workflow，4 phase）</strong>：</p><ol><li><strong>Claim-Validate</strong>：抽取 codex-rewrite 27 條原子 claim + 4 條 design-delta；7 個驗證 agent 各讀一主題桶論文（覆蓋 60+ 篇，含大量 2026 一手 harness 論文），對每條 claim 標 CONFIRM/REFUTE/NUANCE/NOT_COVERED + 論文錨點 + 數字。</li><li><strong>Pilot-Review</strong>：4 pilot 從四維評審（haiku=成本/byte、sonnet=繁中品質、opus=workspace 彈性架構、fable=對抗稽核）。<strong>fable 不可用 → 4 pilot 缺 1。</strong></li><li><strong>Judge-Synth</strong>：opus xhigh 綜合判定 + 融合草案（5 條規則）。</li><li><strong>Adversarial</strong>：逐條對抗驗證。<strong>fable 全失敗 → opus 接手稽核</strong>（fresh-context verifier；P1 fallback 原則現實版）。</li></ol><p><strong>Fable 5 不可用事件</strong>：workflow 中所有 fable model 的 agent 失敗（&quot;Claude Fable 5 is currently unavailable&quot;）。<strong>這恰好驗證了兩件事</strong>：(a) 現有 MEMORY 洞察「Fable cyber/bio silent fallback → Opus」的部署現實；(b) codex-rewrite prompt-lifecycle 的「不可跨 generation/provider 直接移植」警告——能力不在時，harness 必須有 fallback 路徑。本報告用 opus 接手稽核，符合 workspace「generator≠evaluator」+ Fable 5 official「fresh-context verifier &gt; self-critique」。</p><h2 id="_1-兩家風格對照-高層" tabindex="-1">1. 兩家風格對照（高層） <a class="header-anchor" href="#_1-兩家風格對照-高層" aria-label="Permalink to &quot;1. 兩家風格對照（高層）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>現有 Zeuik harness</th><th>ChatGPT 5.5 codex-rewrite</th></tr></thead><tbody><tr><td>語言</td><td>繁中為主（術語英文），繁中鐵律 + session-tail override</td><td>英文為主，2 行語言指令無例外條款</td></tr><tr><td>auto-load byte</td><td>18,713/19,000（byte = canonical 單位，tokenizer 免疫）</td><td>~10,943（−41.5%，但無 byte cap 鐵律）</td></tr><tr><td>The Loop</td><td>六階段 + 21+ MEMORY lesson 接地 + refs 分層</td><td>六階段精煉、failure-mode 導向、去 workspace 化</td></tr><tr><td>Task Contract</td><td>隱含在 IDENTIFY</td><td><strong>顯式 Goal/Context/Constraints/Done-when 四欄（新結構）</strong></td></tr><tr><td>失敗詞彙</td><td>core.md:58「失敗歸因到層」但<strong>未具名層</strong></td><td><strong>7 層 ETCLOVG 顯式（execution/tool/context/lifecycle/observability/verification/governance）</strong></td></tr><tr><td>security</td><td>path-scoped 中文 + 紅線列舉</td><td><strong>5-tier risk + escalation ladder + recovery 流程</strong></td></tr><tr><td>substrate wiring</td><td>pilot 路由 / multi-mode / RESOLVER / refs / inline-mirror sync 全接線</td><td><strong>完全未提及 SKILLS/AGENTS/HOOKS/RESOLVER</strong></td></tr><tr><td>記憶</td><td>MEMORY.md 23 session 接地（失敗→防範）</td><td>零持久記憶（&quot;rules are immutable static rules&quot;）</td></tr><tr><td>自我演化 gate</td><td>/autoload-evolution 硬 gate（≤1 規則/cycle、eval ≥5pp → revert）</td><td>&quot;Change Gate&quot; 僅 advisory checklist</td></tr></tbody></table><p><strong>核心張力</strong>：ChatGPT 5.5 供了<strong>更好的 typed 概念骨架</strong>，但<strong>以全盤省略 substrate 來「精簡」</strong>——這不是健康簡化，是 3 篇論文反駁的設計動作（durable project-local Control artifacts ARE the harness）。現有 Zeuik <strong>接線每個 substrate 元素但缺 typed backbone</strong>，留 18 agents ad-hoc 歸因失敗。</p><h2 id="_2-論文驗證結果-27-claim-主對話親-grep-重驗-3-核心錨點" tabindex="-1">2. 論文驗證結果（27 claim，主對話親 grep 重驗 3 核心錨點） <a class="header-anchor" href="#_2-論文驗證結果-27-claim-主對話親-grep-重驗-3-核心錨點" aria-label="Permalink to &quot;2. 論文驗證結果（27 claim，主對話親 grep 重驗 3 核心錨點）&quot;">​</a></h2><p>完整 verdict 見 workflow 輸出。摘要 + <strong>主對話親驗錨點</strong>（不信 agent verdict）：</p><h3 id="_2-1-confirm-論文強支持" tabindex="-1">2.1 CONFIRM（論文強支持） <a class="header-anchor" href="#_2-1-confirm-論文強支持" aria-label="Permalink to &quot;2.1 CONFIRM（論文強支持）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Claim</th><th>Verdict</th><th>論文錨點（★ = 主對話親 grep 驗證）</th></tr></thead><tbody><tr><td>CL1 四 runtime 能力 = harness 有效性來源</td><td>CONFIRM HIGH</td><td>★ <strong>2606-10106 what-makes-harness</strong>：逐字「iff 四元素：(i)agent loop (ii)tool interface (iii)context management (iv)control mechanisms」；temporal clause load-bearing（harness 在任務中作用，eval harness 在之後）。親驗精確。</td></tr><tr><td>CL2 無可驗證 control 的「完成」= 自述</td><td>CONFIRM HIGH</td><td>2606-10106 T4「control 須不依賴模型服從」；2605-13357 形式化為 <code>unverified_success</code> outcome label。</td></tr><tr><td>CL11 sub-agent verdict = 中間證據，parent 須確定性重驗</td><td>CONFIRM HIGH</td><td>2605-15221 Vesper「Generator ≠ Evaluator」；2606-10106 T4。</td></tr><tr><td>CL12 修補前先歸因（attribution-before-repair）</td><td>NUANCE→CONFIRM</td><td>★ <strong>2606-06324 HarnessFix</strong>：逐字「ETCLOVG = Execution/Tool-interface/Context-memory/Lifecycle/Observability/Verification/Governance」，改進 harness <strong>15.2%–50.0%</strong>，論文<strong>自行對應</strong> core.md「失敗歸因到層」。親驗精確。<strong>但 7 層是 HarnessFix 詞彙，非 workspace 發明</strong>（須標來源，Lesson 2026-06-05-G）。</td></tr><tr><td>CL13 自我改進須 evaluator-grounded（非 LLM 自評）</td><td>CONFIRM HIGH</td><td>2604-25850 AHE「每 edit 配 falsifiable prediction，驗證後 revert 無效 edit」；fix precision 33.7%（5× random）。</td></tr><tr><td>CL14 LLM 判斷 / 確定性代碼決定</td><td>CONFIRM HIGH</td><td>2603-25723 NLAH「NL 不取代確定性代碼」；2606-10106 T4「deterministic containment 最強 control」。</td></tr><tr><td>CL3 具名 Task-Contract（→ Handoff）</td><td>NUANCE</td><td>★ <strong>2503-13657 MAST</strong>：κ=0.88、<strong>Specification Issues = 三大失敗類之首</strong>、「Specification 品質是 MAS 天花板」。親驗精確。但 4 欄精確集是設計選擇，非論文強制。</td></tr></tbody></table><h3 id="_2-2-nuance-論文限定-校準" tabindex="-1">2.2 NUANCE（論文限定/校準） <a class="header-anchor" href="#_2-2-nuance-論文限定-校準" aria-label="Permalink to &quot;2.2 NUANCE（論文限定/校準）&quot;">​</a></h3><ul><li><strong>CL7 4-axis Done-when</strong>：security/reliability/maintainability 是論文 grounded 軸（Claude Code Five Values + 2605-13357 Entropy auditor），但無論文規定「綁成單一 4-axis 完成閘」——它們是分離的 harness 元件/values。</li><li><strong>CL12 7 層</strong>：attribution-before-repair 強確認，但 HarnessFix 是 8 type taxonomy + 11 components，<strong>非 codex 的 7 層</strong>——7 層是 workspace synthesis（仍對應 ETCLOVG）。</li><li><strong>CL15 critical context 放 HEAD/TAIL</strong>：Lost-in-the-Middle（2307-03172）確認 HEAD 最可靠，但 codex 未量化中段衰退幅度。</li><li><strong>DX1 具名 Task-Contract</strong>：generic block 反而 regress（萃取 100→90%）→ <strong>須 task-calibrated 非靜態樣板</strong>。</li></ul><h3 id="_2-3-反向發現-neither-harness-捕捉-候選新規則" tabindex="-1">2.3 反向發現（neither harness 捕捉，候選新規則） <a class="header-anchor" href="#_2-3-反向發現-neither-harness-捕捉-候選新規則" aria-label="Permalink to &quot;2.3 反向發現（neither harness 捕捉，候選新規則）&quot;">​</a></h3><p>各桶 INSIGHTS 浮現 3 個 neither 版本捕捉的點：</p><ol><li><strong>model-switching-as-control</strong>（2606-10106 + 2605-12239）：verifier-score threshold 自動升級模型 tier = 確定性 control。</li><li><strong>verification-stringency-scales-with-capability</strong>（Vesper：GPT-5.2-codex 駭 eval 16.6% vs codex-mini 0%；Opus 4.7 test-cheat 45%→12.5% 僅 with anti-hack prompt）：越強模型越該升 verifier 嚴格度。</li><li><strong>memory write-gate / partition</strong>（faulty-memory 2605-12978 非單調效用；Mnemonic-Sovereignty 2604-16548 memory = 攻擊面）：自寫 lesson = untrusted write surface 需 rollback。</li></ol><h2 id="_3-多維-pilot-評審-4-維-fable-缺位-→-opus-補對抗" tabindex="-1">3. 多維 pilot 評審（4 維，fable 缺位 → opus 補對抗） <a class="header-anchor" href="#_3-多維-pilot-評審-4-維-fable-缺位-→-opus-補對抗" aria-label="Permalink to &quot;3. 多維 pilot 評審（4 維，fable 缺位 → opus 補對抗）&quot;">​</a></h2><h3 id="_3-1-haiku-成本-byte" tabindex="-1">3.1 haiku（成本/byte） <a class="header-anchor" href="#_3-1-haiku-成本-byte" aria-label="Permalink to &quot;3.1 haiku（成本/byte）&quot;">​</a></h3><ul><li>ChatGPT 5.5 <strong>−41.5% byte</strong>（10,943 vs 18,713）、CJK overhead −38%、cache-hit 80-85% vs Zeuik 72%。</li><li><strong>但反轉</strong>：零記憶 = 丟掉 MEMORY 23 session 接地（grounding IS the harness）；byte 省不抵 learning + grounding 損失。</li><li><strong>CROSSBRED</strong>：hybrid refs（高頻 inline、深度 path-scoped）；episodic-gated memory（防退化 gate）；cache-hit 列一級指標。</li></ul><h3 id="_3-2-sonnet-繁中品質-—-決定性結論" tabindex="-1">3.2 sonnet（繁中品質）— <strong>決定性結論</strong> <a class="header-anchor" href="#_3-2-sonnet-繁中品質-—-決定性結論" aria-label="Permalink to &quot;3.2 sonnet（繁中品質）— **決定性結論**&quot;">​</a></h3><ul><li>ChatGPT 5.5 規則幾乎全英文 + 2 行語言指令無例外條款 + 無 CJK tax 意識 + 無 compact 語言保留 + 無 session-tail override → <strong>移除每一個讓繁中穩定的營運防護</strong>。</li><li>實證：llms-get-lost 多輪 adherence 衰退 +112%、無 front-load consolidation 僅 15-20% 復原；beyond-context-window compaction 毀 ~25% constraint-class（語言 register 正是此類）；Lost-in-the-Middle HEAD 最可靠。</li><li>現有 harness 正確把「繁體中文優先」放第一 token、session-tail override 標 IMPORTANT、CJK split、compact hint 保留繁中——全 production grounded（Lesson 2026-06-07-G）。</li><li><strong>值得採 2 點</strong>：sub-agent handoff 顯式寫 rules（語言繼承）+ post-compact re-anchor。</li></ul><h3 id="_3-3-opus-workspace-彈性架構-—-決定性結論" tabindex="-1">3.3 opus（workspace 彈性架構）— <strong>決定性結論</strong> <a class="header-anchor" href="#_3-3-opus-workspace-彈性架構-—-決定性結論" aria-label="Permalink to &quot;3.3 opus（workspace 彈性架構）— **決定性結論**&quot;">​</a></h3><ul><li>兩版<strong>反方向失敗</strong>：ChatGPT 5.5 供 superior typed scaffold 但<strong>全盤省略 substrate</strong>；Zeuik 接線每元素但缺 typed backbone。</li><li><strong>融合 backbone</strong>：開頭放四 runtime 能力，把 SKILLS→tool-interface / AGENTS→agent-loop / HOOKS→deterministic-control / refs→context-management 映上去；ONE task-calibrated Task-Contract（加 [mode:] 欄）；ETCLOVG 為共用失敗詞彙；5-tier 綁 HOOK；保留 pilot 路由 / refs 分層 / byte-cap / inline-mirror。</li></ul><h3 id="_3-4-opus-對抗稽核-補-fable-缺口-—-推翻-synth-多項過度樂觀" tabindex="-1">3.4 opus 對抗稽核（補 fable 缺口）— <strong>推翻 synth 多項過度樂觀</strong> <a class="header-anchor" href="#_3-4-opus-對抗稽核-補-fable-缺口-—-推翻-synth-多項過度樂觀" aria-label="Permalink to &quot;3.4 opus 對抗稽核（補 fable 缺口）— **推翻 synth 多項過度樂觀**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>規則</th><th>對抗 verdict</th><th>理由</th></tr></thead><tbody><tr><td>R1 Runtime Contract（+290B）</td><td><strong>REVISE 壓縮 / DEFER</strong></td><td>Half-A 是 CLAUDE.md:8 複述；workspace mapping 是「可推導=噪音」(core.md:47)；唯一淨值 = framing 句。+290B 破硬 cap。</td></tr><tr><td>R2 ETCLOVG（+60B）</td><td><strong>REVISE 縮到 ~20B refs 指針</strong></td><td>core.md:58 已有「失敗歸因到層」；7 詞 taxonomy 屬 refs 不屬 auto-load。</td></tr><tr><td>R3 Task-Contract（Handoff）</td><td><strong>KEEP（最強）</strong></td><td>grep 確認 subagent-strategy 無 Goal/Done-when/Allowed-paths → 真淨新增、有真實失敗背書（Lesson 2026-06-04-C/2026-06-14-A 子產物落錯 worktree）。<strong>但「~0B」是假的</strong>，實際 +150-250B。</td></tr><tr><td>R4 繁中 compact 第 4 項（+35B）</td><td><strong>DROP</strong></td><td>繁中 after-compact 已在 core.md:9 + context-management:11 兩處 → 第 3 份重複；<strong>Lesson 2026-06-07-G 已證純文字強化無效</strong>，R4 正是被記為無效的動作。</td></tr><tr><td>R5 SafeHarness 5-tier</td><td><strong>REVISE 去重</strong></td><td>path-scoped cap-free，但與既有 No-Commit/Boundary/destructive 三列重複 → 第 4 列「矛盾不混用」陷阱（core.md:70）；「HOOK enforced」overclaim。</td></tr></tbody></table><h2 id="_4-關鍵裁決議題-對抗稽核浮現" tabindex="-1">4. 關鍵裁決議題（對抗稽核浮現） <a class="header-anchor" href="#_4-關鍵裁決議題-對抗稽核浮現" aria-label="Permalink to &quot;4. 關鍵裁決議題（對抗稽核浮現）&quot;">​</a></h2><h3 id="_4-1-byte-cap-—-不上調-紅線" tabindex="-1">4.1 byte cap — <strong>不上調</strong>（紅線） <a class="header-anchor" href="#_4-1-byte-cap-—-不上調-紅線" aria-label="Permalink to &quot;4.1 byte cap — **不上調**（紅線）&quot;">​</a></h3><ul><li>synth 提「(a) 上調 cap 到 19,200」<strong>直接違反 core.md:79</strong>（「不接受為塞單一新規則反推湊 byte」）→ <strong>移出選項</strong>。</li><li>主對話親測：<strong>18,713/19,000 = 287B headroom</strong>（canonical 六源；MEMORY 記的 18,967 已過時）。</li><li>正解：<strong>defer/refs-pointer R1 + 每 cycle ≤1 壓縮規則</strong>（core.md:80）。</li></ul><h3 id="_4-2-不可一次落-5-規則" tabindex="-1">4.2 不可一次落 5 規則 <a class="header-anchor" href="#_4-2-不可一次落-5-規則" aria-label="Permalink to &quot;4.2 不可一次落 5 規則&quot;">​</a></h3><ul><li>core.md:80 = ≤1 規則/cycle、≤50 行 diff。crossbred-as-drafted <strong>獨立於 byte 數即違反 autoload-evolution gate</strong>。</li><li><strong>落地優先序</strong>：R3（真 gap，ChatGPT 5.5 authored — 須 credit）&gt; R1-壓縮或 defer &gt; R2-refs 指針 &gt; R5-去重。<strong>R4 DROP</strong>。</li></ul><h3 id="_4-3-home-team-bias-校正" tabindex="-1">4.3 home-team bias 校正 <a class="header-anchor" href="#_4-3-home-team-bias-校正" aria-label="Permalink to &quot;4.3 home-team bias 校正&quot;">​</a></h3><p>opus 對抗稽核抓出 synth「crossbred beats both」有 home-team 味。ChatGPT 5.5 被低估 3 處：</p><ol><li><strong>R3 Handoff Contract — ChatGPT 寫得更好</strong>（顯式 Non-goals + Allowed-paths + Return-format，現有 workspace 全無）→ R3 ~90% 是 ChatGPT 內容，須 credit。</li><li><strong>codex「delta updates over full rewrites」+「commit only when user asks」</strong> 比現有更銳利（現有 core.md:95「改動完成 YOU MUST git add」可能 over-commit）。</li><li><strong>結構簡潔/maintainability 軸</strong>（core.md:34 四軸品質之一）favor ChatGPT 更多——現有 harness 累積了 rewrite 已 shed 的 clutter。</li></ol><ul><li><strong>修正結論</strong>：「crossbred beats both」應降為「<strong>僅當採 ChatGPT 結構（R3/R5）+ 守既有 byte-cap governance 時</strong> crossbred 才勝；as-drafted 違反 cap + cycle gate，比兩個 parent 都差<strong>直到修正</strong>」。</li></ul><h2 id="_5-融合規則最終草案-經對抗稽核修正" tabindex="-1">5. 融合規則最終草案（經對抗稽核修正） <a class="header-anchor" href="#_5-融合規則最終草案-經對抗稽核修正" aria-label="Permalink to &quot;5. 融合規則最終草案（經對抗稽核修正）&quot;">​</a></h2><blockquote><p><strong>原則</strong>：採 ChatGPT 5.5 最佳 typed 結構<strong>僅在 pilot+論文確認價值處</strong>；保留 Zeuik 防過真實失敗的 grounding；嚴守 byte cap 不上調 + ≤1 規則/cycle。</p></blockquote><h3 id="落地優先序-建議分-cycle" tabindex="-1">落地優先序（建議分 cycle） <a class="header-anchor" href="#落地優先序-建議分-cycle" aria-label="Permalink to &quot;落地優先序（建議分 cycle）&quot;">​</a></h3><p><strong>Cycle 1（最高價值，建議先做）— R3 Task-Contract / Handoff</strong></p><ul><li>落 <code>.claude/rules/subagent-strategy.md</code>。採 ChatGPT 5.5 的 Handoff Contract（Goal/Non-goals/Allowed-paths/Context/Done-when/Return-format）+ Zeuik 加 <code>語言模式:繁中</code> 欄 + <code>[mode:]</code> 路由欄；標 task-calibrated（非靜態）。</li><li>失敗模式：MAST spec-ambiguity = #1 MAS failure；子產物落錯 worktree（Lesson 2026-06-04-C/2026-06-14-A）。</li><li>byte：實際 +150-250B（非 synth 的「~0B」）→ 須先壓 subagent-strategy 或核可上調以外的取回。</li></ul><p><strong>Cycle 2 — R1 Runtime Contract（壓縮版或 refs 化）</strong></p><ul><li>若 ≥250B headroom：壓縮版（~200B blockquote，去 Half-A 複述 + workspace mapping，僅留四能力 framing + 「更長 prompt ≠ 更好 harness」）。</li><li>若 &lt;100B：refs 指針（≤40B：<code>&gt; Harness=loop+tools+context+control 四能力（見 refs/harness-loop.md）</code>）+ 全文入 refs。</li></ul><p><strong>Cycle 3 — R2 ETCLOVG refs 指針</strong></p><ul><li>core.md:58 末加 <code>（七層詞彙見 refs/harness-loop.md）</code>（~+20B），全 7 層入 refs。</li></ul><p><strong>R5 — security-hygiene 去重融合</strong></p><ul><li>path-scoped（cap-free）。採 escalation ladder <em>概念</em>，tiers 折進既有結構（不另立第 4 列），不 overclaim HOOK enforcement。</li></ul><p><strong>R4 — DROP</strong>（繁中第 3 份重複，違反 Lesson 2026-06-07-G）。</p><h3 id="open-question-triage-對抗稽核" tabindex="-1">Open-question triage（對抗稽核） <a class="header-anchor" href="#open-question-triage-對抗稽核" aria-label="Permalink to &quot;Open-question triage（對抗稽核）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>議題</th><th>triage</th><th>理由</th></tr></thead><tbody><tr><td>model-switching-as-control</td><td><strong>HIGH_VALUE</strong></td><td>CLAUDE.md:22 Fable→Opus fallback + 本 session Fable 不可用實證 = 已依賴的 control，形式化有失敗背書</td></tr><tr><td>memory write-gate</td><td><strong>HIGH_VALUE</strong></td><td>多次污染記憶寫入（Lesson 2026-06-04-D / 2026-06-14-C；Fable Ex3 自欺寫入 memory）；落 memory-compactor SKILL（zero auto-load）</td></tr><tr><td>verification-stringency-scales</td><td><strong>ACADEMIC_DEFER</strong></td><td>無「強模型需更少驗證反被燒」的真實失敗；推測性</td></tr></tbody></table><h2 id="_6-繁中-workspace-彈性最終判定-回答使用者-2-問" tabindex="-1">6. 繁中 + workspace 彈性最終判定（回答使用者 2 問） <a class="header-anchor" href="#_6-繁中-workspace-彈性最終判定-回答使用者-2-問" aria-label="Permalink to &quot;6. 繁中 + workspace 彈性最終判定（回答使用者 2 問）&quot;">​</a></h2><p><strong>(a) 哪版繁中更好？</strong> — <strong>現有 Zeuik 決定性勝</strong>。ChatGPT 5.5 全英文 rule body 會在 session 後段/compact 後<strong>量測上衰退繁中遵從</strong>（auto-load prefix 是語言模式主錨點；Lesson 2026-06-14-G）。融合策略：<strong>rule 檔保持繁中</strong>，僅採 ChatGPT 的 handoff 顯式化 + post-compact re-anchor。</p><p><strong>(b) 哪版 workspace 彈性更高？</strong> — <strong>融合版勝</strong>。ChatGPT 5.5 的 typed backbone（四能力 + ETCLOVG + Task-Contract + 5-tier）是讓 29-skill/18-agent substrate <strong>可組合</strong>的 typed schema；但它<strong>全盤省略 substrate 會 flatten</strong>。把 Zeuik 已驗證 substrate（pilot 路由 / RESOLVER / refs 分層 / inline-mirror / byte-cap）<strong>掛上</strong> ChatGPT 5.5 的 backbone → 嚴格比兩個 parent 都更有彈性。</p><h2 id="_7-殘留風險與下一步" tabindex="-1">7. 殘留風險與下一步 <a class="header-anchor" href="#_7-殘留風險與下一步" aria-label="Permalink to &quot;7. 殘留風險與下一步&quot;">​</a></h2><ul><li><strong>未套用</strong>：本報告為交付物，融合規則<strong>未動 auto-load</strong>（守先報告後裁決）。套用走 <code>/autoload-evolution</code> gated loop，每 cycle ≤1 規則。</li><li><strong>byte 取回前提</strong>：R3 落地需先壓 subagent-strategy 取回 ~200B，或從別處壓——<strong>不上調 cap</strong>。</li><li><strong>Fable 不可用</strong>：對抗稽核由 opus 代行；若 Fable 恢復，可重跑 adversarial phase 交叉驗證（非必要，opus 稽核已 grounded）。</li><li><strong>驗證狀態</strong>：3 核心論文錨點主對話親 grep 驗證 exit=0；byte canonical 六源重測；對抗稽核推翻 synth 過度樂觀項。healthcheck 待 commit 前跑。</li></ul>',56)])])}const p=e(s,[["render",n]]);export{u as __pageData,p as default};
